"""Admin operations UI; data actions require explicit clicks and server authorization."""

# ruff: noqa: E501
ADMIN_CONTROLS = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin controls · BluQQ</title>
<style>:root{font:15px system-ui;color:#192a42;background:#f3f6fb}*{box-sizing:border-box}body{margin:0}header{background:#101d33;color:white;padding:22px max(20px,5vw);display:flex;gap:18px;align-items:center;flex-wrap:wrap}header h1{font-size:23px;margin:0;flex:1}header a{color:#b5d9ff}main{max-width:1400px;margin:auto;padding:24px}section{background:white;border:1px solid #dce4ef;border-radius:12px;margin:18px 0;padding:20px}h2{font-size:18px;margin:0 0 10px}.sub{font-size:13px;color:#61718a;line-height:1.6}.warning{background:#fff5dd;border:1px solid #eac575;border-radius:10px;padding:16px;line-height:1.6}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button{font:inherit;font-size:13px;padding:9px 13px;background:#edf2fa;color:#17283e;border:1px solid #cfdaeb;border-radius:7px;cursor:pointer}button:disabled{opacity:.5;cursor:wait}.danger{color:#a52b34;border-color:#e2a7ae;background:#fff5f5}.primary{background:#275be4;color:white;border-color:#275be4}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:12px 9px;border-bottom:1px solid #e8edf5;vertical-align:top}th{background:#f8faff;font-size:12px;color:#60718a}td{max-width:420px;overflow-wrap:anywhere}#notice{white-space:pre-wrap;padding:10px 0;min-height:38px}.metrics{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}.metric{background:white;border:1px solid #dce4ef;border-radius:10px;padding:16px}.metric b{display:block;font-size:27px;margin-top:8px}a{color:#275be4}[hidden]{display:none!important}button:focus-visible,a:focus-visible{outline:3px solid #99c2ff;outline-offset:2px}</style></head><body>
<header><h1>BluQQ · Admin controls</h1><a href="/linkedin-automation/">Shared dashboard</a><a href="/linkedin-automation/connect-computer">Connect this computer</a><a href="/linkedin-automation/login">Google / email login</a><button id="logout">Sign out</button></header><main>
<div class="toolbar"><strong id="identity">Checking administrator…</strong><button id="refresh">Refresh status</button></div><div id="notice" role="status" aria-live="polite"></div><div id="release" class="warning"></div><p class="sub">This panel manages approved access, device credentials and operational metadata. Private lead profiles and message drafts are not exposed here. No action on this page sends LinkedIn outreach.</p><div id="metrics" class="metrics"></div>
<section><h2>Approved user access</h2><p class="sub">Only owner-configured emails can be enabled. Blocking access revokes web sessions and denies workers immediately; stored research stays intact. Google test-audience configuration remains an owner task.</p><div class="table"><table><thead><tr><th>Email</th><th>Account</th><th>Access</th><th>Paired devices</th><th>Action</th></tr></thead><tbody id="users"></tbody></table></div></section>
<section><h2>Paired computers</h2><p class="sub">Online means a heartbeat in the last 45 seconds. Revocation blocks future claims/imports; it cannot remotely close a browser already open on another PC. The user must pair again after revocation.</p><div class="table"><table><thead><tr><th>Computer</th><th>Workspace</th><th>Status</th><th>Last heartbeat</th><th>Action</th></tr></thead><tbody id="devices"></tbody></table></div></section>
<section><h2>Recent searches and failures</h2><p class="sub">Up to 60 recent searches. Only queued searches can be cancelled here. Running collection must be stopped on its own PC. Missing/hidden LinkedIn profiles cannot be unlocked by an API key.</p><div class="table"><table><thead><tr><th>Workspace / campaign</th><th>Job</th><th>Status</th><th>Read / saved</th><th>Result</th><th>Action</th></tr></thead><tbody id="jobs"></tbody></table></div></section>
<section><h2>Server configuration</h2><p class="sub">Presence checks only; secret values are never displayed and providers are not called. Keys saved on a local PC are not server configuration.</p><div class="table"><table><thead><tr><th>Integration</th><th>Configuration</th><th>Purpose / remaining work</th></tr></thead><tbody id="configuration"></tbody></table></div><p id="modes" class="sub"></p></section>
<section><div class="toolbar"><h2>Database snapshots</h2><button class="primary" id="backup">Create server snapshot</button></div><p id="backupNote" class="sub"></p><p class="sub">Snapshot contents are not downloadable through this panel. No restore or deletion action is provided.</p><div class="table"><table><thead><tr><th>Snapshot</th><th>Created</th><th>Database files</th><th>Status</th></tr></thead><tbody id="backups"></tbody></table></div></section>
<section><h2>Admin action history</h2><div class="table"><table><thead><tr><th>Time</th><th>Administrator</th><th>Action</th><th>Target</th></tr></thead><tbody id="events"></tbody></table></div></section></main>
<script>
const $=id=>document.getElementById(id), date=value=>value?new Date(value*1000).toLocaleString():'Never';
async function api(path,payload){const response=await fetch('/linkedin-automation'+path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const value=await response.json();if(!response.ok){if(response.status===401)location.assign('/linkedin-automation/admin');throw Error(value.detail||'Operation failed');}return value;}
function row(target,values,action){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=String(value??'');tr.append(td);}if(action){const td=document.createElement('td');if(action.label){const button=document.createElement('button');button.textContent=action.label;button.className=action.danger?'danger':'';button.onclick=async()=>{if(!confirm(action.confirm))return;button.disabled=true;try{await api(action.url,action.payload);$('notice').textContent=action.success||'Admin action completed.';await refresh();}catch(error){$('notice').textContent=error.message;}finally{button.disabled=false;}};td.append(button);}tr.append(td);}$(target).append(tr);}
function empty(target,columns){if(!$(target).children.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=columns;td.textContent='No records.';tr.append(td);$(target).append(tr);}}
async function refresh(){const value=await api('/api/admin/overview');for(const id of ['users','devices','jobs','configuration','backups','events','metrics'])$(id).replaceChildren();$('release').textContent=value.release_blocker;$('backupNote').textContent=value.backup_note;$('modes').textContent='Signup: '+value.signup_mode+' · Cloud mode: '+(value.cloud_enabled?'enabled':'disabled')+' · Desktop sending: disabled';for(const [label,count] of [['Approved emails',value.users.length],['Online devices',value.devices.filter(d=>d.online).length],['Recent failed searches',value.jobs.filter(j=>j.status==='failed').length]]){const card=document.createElement('div');card.className='metric';card.textContent=label;const b=document.createElement('b');b.textContent=count;card.append(b);$('metrics').append(card);}for(const user of value.users)row('users',[user.email,user.registered?user.name:'Not signed in yet',user.enabled?'Enabled':'Blocked',user.devices],{label:user.enabled?'Block access':'Restore access',danger:user.enabled,url:'/api/admin/access',payload:{email:user.email,enabled:!user.enabled},confirm:(user.enabled?'Block':'Restore')+' access for '+user.email+'? Research data will be retained.'});for(const device of value.devices)row('devices',[device.label,device.email,device.revoked?'Revoked':device.online?'Online':'Offline',date(device.last_seen)],device.revoked?{}:{label:'Revoke device',danger:true,url:'/api/admin/devices/revoke',payload:{id:device.id},confirm:'Revoke '+device.label+' for '+device.email+'? Already running browsers must be closed on that PC.'});for(const job of value.jobs)row('jobs',[job.email+' · '+job.campaign,job.id,job.status,job.observed+' / '+job.saved,job.message],job.status==='queued'?{label:'Cancel queued',danger:true,url:'/api/admin/search/cancel',payload:{scope:job.scope,id:job.id},confirm:'Cancel this queued search? No saved research will be deleted.'}:{});for(const item of value.configuration)row('configuration',[item.name,item.configured?'Configured':'Missing / not configured',item.note]);for(const snapshot of value.backups)row('backups',[snapshot.id,date(snapshot.created),snapshot.files,snapshot.complete?'Complete':'Incomplete']);for(const event of value.events)row('events',[date(event.created),event.actor,event.action.replaceAll('_',' '),event.target]);for(const [id,cols] of [['users',5],['devices',5],['jobs',6],['configuration',3],['backups',4],['events',4]])empty(id,cols);}
$('refresh').onclick=()=>refresh().catch(error=>$('notice').textContent=error.message);$('backup').onclick=async()=>{if(!confirm('Create snapshots of the application databases on the current Railway volume? This does not restore, delete or download private data.'))return;$('backup').disabled=true;try{const result=await api('/api/admin/backups',{});$('notice').textContent='Snapshot '+result.id+': '+result.files+' database files.';await refresh();}catch(error){$('notice').textContent=error.message;}finally{$('backup').disabled=false;}};$('logout').onclick=async()=>{try{await api('/api/auth/logout',{});location.assign('/linkedin-automation/admin');}catch(error){$('notice').textContent=error.message;}};api('/api/auth/me').then(user=>{if(user.role!=='admin'){location.assign('/linkedin-automation/admin');return;}$('identity').textContent='Administrator: '+user.username;return refresh();}).catch(error=>$('notice').textContent=error.message);
</script></body></html>'''
